import json
def comps(G, bg):
    from collections import deque
    R,C=len(G),len(G[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for i in range(R):
        for j in range(C):
            if not seen[i][j] and G[i][j]!=bg:
                col=G[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<R and 0<=nb<C and not seen[na][nb] and G[na][nb]==col:
                            seen[na][nb]=True; q.append((na,nb))
                out.append({'color':col,'n':len(cells),'cells':sorted(cells)})
    return out

def norm(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in cells))

